corrected_code:
const { DynamoDBClient } = require('@aws-sdk/client-dynamodb');
const { DynamoDBDocumentClient, UpdateCommand } = require('@aws-sdk/lib-dynamodb');
const ddb = DynamoDBDocumentClient.from(new DynamoDBClient({}));

exports.handler = async (event) => {
  const invoiceId = event.pathParameters.invoiceId;
  const customerId = event.requestContext.authorizer.claims.sub;
  try {
    const result = await ddb.send(new UpdateCommand({
      TableName: 'Invoices',
      Key: { id: invoiceId },
      ConditionExpression: 'customerId = :cid',
      UpdateExpression: 'SET #st = :st, reissuedAt = :now',
      ExpressionAttributeNames: { '#st': 'status' },
      ExpressionAttributeValues: { ':st': 'REISSUED', ':now': new Date().toISOString(), ':cid': customerId },
      ReturnValues: 'ALL_NEW'
    }));
    return { statusCode: 200, body: JSON.stringify(result.Attributes) };
  } catch (err) {
    if (err.name === 'ConditionalCheckFailedException') {
      return { statusCode: 403, body: JSON.stringify({ error: 'Access denied or invoice not found' }) };
    }
    throw err;
  }
};
